import{c as a,Q as t,j as n,m as o}from"./chunks/framework.g_l1frA7.js";const m=JSON.parse('{"title":"Accounts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/accounts.md","filePath":"guide/accounts.md","lastUpdated":null}'),c={name:"guide/accounts.md"};function s(r,e,i,l,d,u){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="accounts" tabindex="-1">Accounts <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;Accounts&quot;">​</a></h1><p>Accounts hold your money and define net worth. FinSight supports manual accounts (you enter and import) and SimpleFIN-synced accounts (pulled from your bank via bridge).</p><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><p><code>checking</code> · <code>savings</code> · <code>credit</code> · <code>investment</code> · <code>cash</code> · <code>loan</code> · <code>other</code></p><p>Each carries a color token (e.g. <code>--c-checking: #60A5FA</code>) used in charts and indicators. Account creation lives in <code>crates/finsight-core::repos/accounts</code>.</p><h2 id="manual-accounts" tabindex="-1">Manual accounts <a class="header-anchor" href="#manual-accounts" aria-label="Permalink to &quot;Manual accounts&quot;">​</a></h2><ol><li><strong>Accounts → Add account</strong> — pick a type, name, and optional opening balance.</li><li>Import history via CSV or add transactions directly.</li><li>Balance history is derived from transactions; you never maintain a separate balance ledger.</li></ol><h2 id="simplefin-accounts" tabindex="-1">SimpleFIN accounts <a class="header-anchor" href="#simplefin-accounts" aria-label="Permalink to &quot;SimpleFIN accounts&quot;">​</a></h2><ol><li>Obtain a SimpleFIN access URL from your bridge.</li><li>Paste it during onboarding or at <strong>Accounts → Connect SimpleFIN</strong>. The URL is stored per-user inside your encrypted <code>data.sqlcipher</code>.</li><li>Press <strong>Synchronize</strong> — FinSight fetches accounts/transactions and merges them. Sync runs and errors are recorded; use them to diagnose a failing sync.</li></ol><p>Removing the access URL stops future syncs; previously imported transactions stay.</p><h2 id="net-worth-balance-history" tabindex="-1">Net worth &amp; balance history <a class="header-anchor" href="#net-worth-balance-history" aria-label="Permalink to &quot;Net worth &amp; balance history&quot;">​</a></h2><p>Net worth = sum(asset accounts) − sum(liability accounts) at the chosen as-of date. Balance history is computed from transactions and shown as a sparkline on Today and a chart on Accounts.</p><h2 id="multi-currency" tabindex="-1">Multi-currency <a class="header-anchor" href="#multi-currency" aria-label="Permalink to &quot;Multi-currency&quot;">​</a></h2><p>FinSight does not invent exchange rates. Holdings in a foreign currency without a known rate are kept in an <code>unconverted</code> bucket and surfaced separately (see <code>CurrencyContext</code>). Totals you see are single-currency; unconverted holdings are listed, not silently summed.</p><h2 id="management" tabindex="-1">Management <a class="header-anchor" href="#management" aria-label="Permalink to &quot;Management&quot;">​</a></h2><ul><li>Edit an account name/type at <strong>Accounts → Manage</strong>.</li><li>Assets/liabilities grouping — the Accounts header shows assets, liabilities, and net; the Drive with household members shows per-member share when enabled.</li><li>Deleting an account removes its transactions only if you choose to; transfers referencing it become standalone rows.</li></ul><p>See also: <a href="/FinSight/guide/transactions">Transactions</a>, <a href="/FinSight/getting-started/importing-data">Importing</a>.</p>',17)])])}const p=a(c,[["render",s]]);export{m as __pageData,p as default};
